package ca.humber.stockbridge.config;
import ca.humber.stockbridge.model.*;import ca.humber.stockbridge.repo.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.BigDecimal;
@Configuration public class SampleData {@Bean CommandLineRunner seed(MaterialRepository m,WarehouseRepository w,SupplierRepository s,StockLotRepository l,AppUserRepository u,PasswordEncoder encoder){return args->{if(m.count()==0){Material copper=m.save(new Material("Copper Wire",Material.Category.NON_FERROUS,new BigDecimal("8.75")));Material aluminum=m.save(new Material("Aluminum",Material.Category.NON_FERROUS,new BigDecimal("2.15")));Material steel=m.save(new Material("Heavy Steel",Material.Category.FERROUS,new BigDecimal("0.32")));Material brass=m.save(new Material("Brass",Material.Category.NON_FERROUS,new BigDecimal("5.10")));Warehouse north=w.save(new Warehouse("North Yard","Toronto, ON","50000"));Warehouse west=w.save(new Warehouse("West Yard","Etobicoke, ON","35000"));Supplier supplier=s.save(new Supplier("Metro Recycling Partners","orders@example.org"));s.save(new Supplier("Lakeshore Metal Supply","contact@example.org"));l.save(new StockLot(copper,north,supplier,new BigDecimal("1200")));l.save(new StockLot(aluminum,west,supplier,new BigDecimal("2450")));l.save(new StockLot(steel,north,supplier,new BigDecimal("8000")));l.save(new StockLot(brass,west,supplier,new BigDecimal("850")));}if(u.count()==0){AppUser admin=new AppUser();admin.fullName="Demo Administrator";admin.email="admin@stockbridge.local";admin.passwordHash=encoder.encode("ChangeMe123!");admin.role="ADMIN";u.save(admin);}};}}